description:
{
  "image_category": "TECHNICAL_DIAGRAM",
  "summary": "Hình ảnh minh họa các loại vạch kẻ đường khác theo QCVN 41:2024/BGTVT, bao gồm vạch cấm quay đầu, vạch dừng đỗ xe công cộng, mũi tên chỉ hướng, mũi tên báo giảm làn, chữ viết trên mặt đường và ký hiệu xe đạp, với đầy đủ kích thước kỹ thuật.",
  "items": [
    {
      "identifier": "Hình G.71 - Vạch cấm xe quay đầu",
      "visual_or_geometric_features": "Hình chữ U ngược (mũi tên quay đầu) với các kích thước: chiều cao tổng 2000 mm, chiều rộng đáy 1000 mm, độ dày nét 100 mm, bán kính cong 500 mm, chiều dài đoạn thẳng 1000 mm.",
      "meaning_or_specification": "Sử dụng vạch màu vàng, hình dáng và kích thước như trên Hình G.71 để chỉ vị trí cấm xe quay đầu tại nút giao hoặc chỗ mở dải phân cách hai chiều."
    },
    {
      "identifier": "Hình G.72 - Vạch quy định vị trí dừng đỗ xe công cộng",
      "visual_or_geometric_features": "Dạng gãy khúc hình chữ M với chiều cao chữ M = 2000 mm, chiều dài đường xiên mỗi bên = 2000 mm, bề rộng nét vẽ b = 100 mm.",
      "meaning_or_specification": "Vạch 9.2 là vạch đơn liền màu vàng, dùng để quy định vị trí dừng đỗ của phương tiện giao thông công cộng; các phương tiện khác và người đi bộ không được dừng, đỗ trong phạm vi vạch và trong khoảng cách 15 m về hai phía theo phương dọc đường."
    },
    {
      "identifier": "Hình G.73 - Mũi tên chỉ hướng (tốc độ thấp)",
      "visual_or_geometric_features": "Mũi tên chỉ hướng với chiều cao 1000 mm, chiều rộng đáy 1000 mm, độ dày nét 100 mm, bán kính cong 500 mm.",
      "meaning_or_specification": "Mũi tên chỉ hướng màu trắng, dùng để chỉ hướng xe phải đi; kích thước này áp dụng cho đường có tốc độ xe chạy thấp."
    },
    {
      "identifier": "Hình G.74 - Mũi tên chỉ hướng (tốc độ cao)",
      "visual_or_geometric_features": "Mũi tên chỉ hướng lớn hơn với chiều cao 1500 mm, chiều rộng đáy 1500 mm, độ dày nét 150 mm, bán kính cong 750 mm.",
      "meaning_or_specification": "Mũi tên chỉ hướng màu trắng, kích thước này áp dụng cho đường có tốc độ xe chạy cao hoặc đường ô tô cao tốc với tốc độ thiết kế ≥ 100 km/h."
    },
    {
      "identifier": "Hình G.75 - Mũi tên báo số làn xe phía trước bị giảm",
      "visual_or_geometric_features": "Mũi tên với hai nhánh phân kỳ, chiều cao 1000 mm, chiều rộng đáy 1000 mm, độ dày nét 100 mm, bán kính cong 500 mm.",
      "meaning_or_specification": "Vạch mũi tên màu trắng báo số làn xe phía trước bị giảm; kích thước này áp dụng cho trường hợp thông thường. Có thể giảm 0,5 lần cho đường tốc độ thấp hoặc tăng 1,5 lần cho đường tốc độ cao."
    },
    {
      "identifier": "Hình G.76 - Kích thước mũi tên báo giảm làn (tốc độ thấp)",
      "visual_or_geometric_features": "Mũi tên với chiều cao 500 mm, chiều rộng đáy 500 mm, độ dày nét 50 mm, bán kính cong 250 mm.",
      "meaning_or_specification": "Kích thước này áp dụng cho đường có tốc độ xe chạy thấp, bằng 0,5 lần kích thước trên Hình G.75."
    },
    {
      "identifier": "Hình G.77 - Vạch chữ 'STOP'",
      "visual_or_geometric_features": "Chữ 'STOP' với chiều cao 1000 mm, bề rộng nét 100 mm, khoảng cách giữa các chữ 100 mm.",
      "meaning_or_specification": "Vạch chữ 'STOP' màu trắng, dùng kèm với các báo hiệu khác để tăng tính rõ ràng; chiều cao chữ 3,0 m cho đường cao tốc, 2,5 m cho đường khác, 1,6 m cho đô thị tốc độ thấp."
    },
    {
      "identifier": "Hình G.78 - Vạch chữ 'Ô TÔ'",
      "visual_or_geometric_features": "Chữ 'Ô TÔ' với chiều cao 1000 mm, bề rộng nét 100 mm, khoảng cách giữa các chữ 100 mm.",
      "meaning_or_specification": "Vạch chữ 'Ô TÔ' màu trắng, dùng để chỉ làn đường dành riêng cho ô tô."
    },
    {
      "identifier": "Hình G.79 - Vạch chữ 'XE MÁY'",
      "visual_or_geometric_features": "Chữ 'XE MÁY' với chiều cao 1000 mm, bề rộng nét 100 mm, khoảng cách giữa các chữ 100 mm.",
      "meaning_or_specification": "Vạch chữ 'XE MÁY' màu trắng, dùng để chỉ làn đường dành riêng cho xe máy."
    },
    {
      "identifier": "Hình G.80 - Vạch chữ 'XE BUÝT'",
      "visual_or_geometric_features": "Chữ 'XE BUÝT' với chiều cao 1000 mm, bề rộng nét 100 mm, khoảng cách giữa các chữ 100 mm.",
      "meaning_or_specification": "Vạch chữ 'XE BUÝT' màu trắng, dùng để chỉ làn đường dành riêng cho xe buýt."
    },
    {
      "identifier": "Hình G.81 - Vạch chữ 'XE ĐẠP'",
      "visual_or_geometric_features": "Chữ 'XE ĐẠP' với chiều cao 1000 mm, bề rộng nét 100 mm, khoảng cách giữa các chữ 100 mm.",
      "meaning_or_specification": "Vạch chữ 'XE ĐẠP' màu trắng, dùng để chỉ làn đường dành riêng cho xe đạp."
    },
    {
      "identifier": "Hình G.82 - Ký hiệu xe đạp",
      "visual_or_geometric_features": "Hình vẽ xe đạp với các kích thước: chiều cao 120 mm, chiều rộng 75 mm (hoặc 170 mm x 275 mm tùy làn xe).",
      "meaning_or_specification": "Vạch ký hiệu xe đạp màu trắng, dùng trên làn đường dành riêng cho xe đạp; kích thước hình vẽ được chọn tùy theo bề rộng của làn xe đạp."
    }
  ]
}
